<script setup lang="ts">
import { ArrowLeftRight, ArrowUpRight, ChevronRight, Download, FileSpreadsheet, FileText, Check, CheckCheck, CircleAlert, RefreshCw, SlidersHorizontal, CalendarDays, Building2, Store, Hash, ArrowRight, X, Plug, ShieldCheck, Info, Search, TrendingUp, Wallet, ReceiptText, LoaderCircle } from 'lucide-vue-next'
import { difference, percent, type DayRow } from '#shared/reconciliation'
import { formatMoney, formatDate, formatPercent } from '~/utils/format'
import { exportExcel } from '~/utils/export'
const { source, webCashboxes, requestedBoxes, changeSource, shiftSkip, shiftTake, demo, status, busy, loading, error, mall, tenant, selected, from, to, mode, malls, tenants, cashboxes, report, stale, refresh, setDemo, changeMall, changeTenant, changeDates, run } = useReconciliation()
watch(source, () => { tab.value = 'all'; detail.value = null })
const tab = ref('all'); const search = ref(''); const auth = ref<null | 'metrix' | 'webkassa'>(null); const login = ref(''); const password = ref(''); const authError = ref(''); const connecting = ref(false); const exporting = ref(false); const detail = ref<DayRow | null>(null)
const rows = computed(() => report.value?.rows || [])
const complete = computed(() => rows.value.length > 0 && rows.value.every(r => difference(r) !== null && !r.error))
const mismatch = computed(() => rows.value.filter(r => difference(r) !== null && difference(r) !== 0 && !r.error).length)
const matched = computed(() => rows.value.filter(r => difference(r) === 0 && !r.error).length)
const totals = computed(() => ({ metrix: rows.value.reduce((s, r) => s + (r.metrix || 0), 0), webkassa: rows.value.reduce((s, r) => s + (r.webkassa || 0), 0), tickets: rows.value.reduce((s, r) => s + r.tickets, 0) }))
const totalRow = computed<DayRow>(() => ({ date: '', metrix: complete.value ? totals.value.metrix : null, webkassa: complete.value ? totals.value.webkassa : null, tickets: totals.value.tickets }))
const filtered = computed(() => rows.value.filter(r => (tab.value === 'all' || (tab.value === 'diff' ? difference(r) !== null && difference(r) !== 0 && !r.error : tab.value === 'matched' ? difference(r) === 0 && !r.error : !!r.error || difference(r) === null)) && formatDate(r.date).includes(search.value)))
const label = (r: DayRow) => r.error || difference(r) === null ? 'Нет данных' : difference(r) === 0 ? 'Совпадает' : 'Расхождение'
function openAuth(service: 'metrix' | 'webkassa') { auth.value = service; login.value = ''; password.value = ''; authError.value = '' }
async function connect() { connecting.value = true; authError.value = ''; try { await $fetch('/api/auth/login', { method: 'POST', body: { service: auth.value, login: login.value, password: password.value } }); status.value = await $fetch<{ metrix: boolean; webkassa: boolean }>('/api/auth/status'); auth.value = null; password.value = ''; if (!demo.value && !malls.value.length) await refresh('malls') } catch (e: any) { authError.value = e?.data?.statusMessage || 'Не удалось подключиться' } finally { connecting.value = false } }
async function disconnect() { try { await $fetch('/api/auth/logout', { method: 'POST' }); status.value = { metrix: false, webkassa: false }; if (!demo.value) await refresh('malls') } catch { error.value = 'Не удалось отключить сервисы' } }
async function excel() { if (!report.value || stale.value) return; exporting.value = true; try { await exportExcel(report.value) } catch { error.value = 'Не удалось создать Excel. Повторите выгрузку.' } finally { exporting.value = false } }
async function print() { const previousTab = tab.value; const previousSearch = search.value; tab.value = 'all'; search.value = ''; await nextTick(); window.print(); tab.value = previousTab; search.value = previousSearch }
function toggleAll() { selected.value = selected.value.length === cashboxes.value.length ? [] : cashboxes.value.map(x => x.name) }
function preset(days: number) { const end = new Date(); end.setDate(end.getDate() - 1); to.value = end.toLocaleDateString('en-CA', { timeZone: 'Asia/Almaty' }); const start = new Date(to.value); start.setUTCDate(start.getUTCDate() - days + 1); from.value = start.toISOString().slice(0, 10); changeDates() }
</script>
<template>
  <div id="reconciliation" class="page">
    <div class="page-heading no-print"><div><div class="eyebrow">ФИНАНСОВАЯ АНАЛИТИКА</div><h1>{{ source === 'both' ? 'Сверка выручки' : source === 'metrix' ? 'Выручка Metrix' : 'Выручка Webkassa' }} <span class="version-badge">WORKSPACE</span></h1><p>Просматривайте выручку по источникам или сравнивайте данные касс.</p></div><button class="btn" :disabled="!report || stale || busy" @click="print"><Download :size="17" />Экспорт PDF</button></div>
    <div class="demo-banner no-print"><div><span class="demo-icon"><Info :size="17" /></span><span><b>{{ demo ? 'Демонстрационный режим' : 'Рабочий режим' }}</b><span class="banner-copy">{{ demo ? 'Посмотрите, как работает сверка, на примере тестовых данных.' : 'Сверка использует данные подключенных сервисов.' }}</span></span></div><label class="switch-label"><span>Демо</span><input type="checkbox" role="switch" :checked="demo" :disabled="busy || loading" @change="setDemo(($event.target as HTMLInputElement).checked)" /><span class="switch" /></label></div>
    <nav class="source-tabs no-print" aria-label="Источник отчета">
      <button type="button" :class="{ active: source === 'both' }" :aria-pressed="source === 'both'" :disabled="busy || loading" @click="changeSource('both')"><ArrowLeftRight :size="16" />Сверка</button>
      <button type="button" :class="{ active: source === 'metrix' }" :aria-pressed="source === 'metrix'" :disabled="busy || loading" @click="changeSource('metrix')"><Wallet :size="16" />Metrix</button>
      <button type="button" :class="{ active: source === 'webkassa' }" :aria-pressed="source === 'webkassa'" :disabled="busy || loading" @click="changeSource('webkassa')"><ReceiptText :size="16" />Webkassa</button>
    </nav>
    <BaseConnections :status="status" @connect="openAuth" @disconnect="disconnect" />
    <section class="card filters no-print"><div class="section-heading"><div class="section-title"><SlidersHorizontal :size="19" /><h2>{{ source === 'both' ? 'Параметры сверки' : 'Параметры отчета' }}</h2></div><span class="muted small">Настройте выборку для вашего отчета</span></div><fieldset :disabled="busy || loading"><div class="filter-grid" :class="{ 'webkassa-filters': source === 'webkassa' }"><div v-if="source !== 'webkassa'"><div class="step-label"><span>1</span>ТОРГОВЫЙ ЦЕНТР</div><UiSelect label="Торговый центр" :model-value="mall" :options="malls" placeholder="Выберите ТЦ" @update:model-value="changeMall" /></div><div v-if="source !== 'webkassa'"><div class="step-label"><span>2</span>АРЕНДАТОР</div><UiSelect label="Арендатор" :model-value="tenant" :options="tenants" placeholder="Все арендаторы" :disabled="!mall" @update:model-value="changeTenant" /></div><div v-if="source !== 'webkassa'"><div class="step-label"><span>3</span>КАССЫ · ЗНК</div><details class="cashbox-select"><summary :class="{ disabled: !mall }"><Hash :size="15" /><span>{{ selected.length ? selected.length === 1 ? selected[0] : `Выбрано касс: ${selected.length}` : 'Выберите кассы' }}</span><ChevronRight :size="15" /></summary><div class="cashbox-options"><button type="button" class="text-btn" :disabled="!cashboxes.length" @click="toggleAll">{{ selected.length === cashboxes.length ? 'Снять выбор' : 'Выбрать все' }}</button><label v-for="box in cashboxes" :key="box.id"><input v-model="selected" type="checkbox" :value="box.name" />{{ box.name }}</label><p v-if="!cashboxes.length" class="muted">{{ mall ? 'Нет касс за выбранный период' : 'Сначала выберите ТЦ' }}</p></div></details></div><label v-if="source === 'webkassa'" class="web-cashboxes"><span class="step-label"><span>1</span>КАССЫ · ЗНК</span><input v-model="webCashboxes" aria-describedby="web-cashboxes-help" placeholder="Например, SWK00507912" /><small id="web-cashboxes-help">Введите ЗНК касс через запятую. До 30 касс.</small></label><div class="period-filter"><div class="step-label"><span>{{ source === 'webkassa' ? 2 : 4 }}</span>ПЕРИОД</div><div class="date-range"><input v-model="from" aria-label="Начало периода" type="date" :max="to" @change="changeDates" /><span>—</span><input v-model="to" aria-label="Конец периода" type="date" :min="from" @change="changeDates" /></div></div></div><details v-if="source !== 'metrix'" class="shift-pagination">
  <summary><span class="shift-heading"><SlidersHorizontal :size="16" /><span>Параметры загрузки смен Webkassa</span></span><ChevronRight class="shift-chevron" :size="16" /></summary>
  <div class="shift-pagination-body">
    <p class="shift-intro">Необязательные настройки. Можно оставить значения по умолчанию.</p>
    <div class="shift-fields">
      <label class="field">
        <span>Skip · пропустить смены</span>
        <input v-model.number="shiftSkip" type="number" min="0" step="1" placeholder="0" aria-describedby="shift-skip-help" />
        <small id="shift-skip-help">Количество смен, которые нужно пропустить. По умолчанию — 0.</small>
      </label>
      <label class="field">
        <span>Take · смен на страницу</span>
        <input v-model.number="shiftTake" type="number" min="1" step="1" placeholder="50" aria-describedby="shift-take-help" />
        <small id="shift-take-help">Количество смен за один запрос. По умолчанию — 50.</small>
      </label>
    </div>
    <p class="shift-note"><Info :size="16" /><span>Следующие страницы загружаются автоматически.</span></p>
    <p class="shift-note shift-skip-note"><CircleAlert :size="16" /><span>При <b>Skip больше 0</b> первые смены не попадут в сверку.</span></p>
  </div>
</details><div class="filter-bottom"><div class="radio-group"><CheckCheck :size="16" /><span>Расчет выручки:</span><b>Продажи − возвраты</b><span v-if="source === 'both'" title="Metrix и Webkassa сравниваются после вычета возвратов">в обоих источниках</span></div><div class="quick-dates"><button type="button" @click="preset(7)">7 дней</button><button type="button" @click="preset(30)">30 дней</button></div><button class="btn primary" :disabled="!requestedBoxes.length || (source !== 'webkassa' && !mall)" @click="run"><RefreshCw v-if="busy" :size="17" class="spin" /><ArrowLeftRight v-else :size="17" />{{ busy ? 'Загружаем данные…' : source === 'both' ? 'Запустить сверку' : 'Загрузить данные' }}</button></div></fieldset><div v-if="loading" class="loading-line"><LoaderCircle :size="15" class="spin" />Загружаем список…</div></section>
    <div v-if="error" class="alert error no-print" role="alert"><CircleAlert :size="19" />{{ error }}<button aria-label="Закрыть ошибку" @click="error = ''"><X :size="17" /></button></div><div v-if="busy" class="alert no-print" role="status"><LoaderCircle :size="18" class="spin" />{{ source === 'metrix' ? 'Получаем дневные итоги Metrix.' : 'Получаем смены и все страницы чеков Webkassa.' }} Большой период может занять несколько минут.</div><div v-if="stale" class="alert no-print"><Info :size="18" />Параметры изменены. Загрузите данные повторно, чтобы обновить отчет и выгрузку.</div>
    <BaseSourceReport v-if="report && report.source && report.source !== 'both'" :report="report" :stale="stale" :busy="busy" :exporting="exporting" @excel="excel" @print="print" />
    <template v-else-if="report"><div class="report-header"><div><h2>Результаты сверки <span v-if="report.demo" class="demo-tag">ДЕМО</span></h2><p>{{ report.mall }}<span> / </span>{{ report.tenant }}<span> · </span>{{ formatDate(report.from) }} — {{ formatDate(report.to) }}</p></div><span class="report-timestamp"><span class="status-dot online" />{{ complete ? 'Сверка завершена' : 'Отчет неполный' }}</span></div>
    <div class="stats-grid"><article class="stat-card"><div class="stat-top"><span>Выручка Metrix</span><span class="stat-icon blue"><Wallet :size="19" /></span></div><div class="stat-value">{{ formatMoney(complete ? totals.metrix : null) }} <span>₸</span></div><div class="stat-foot"><span class="source-dot blue-dot" />Данные учетной системы</div></article><article class="stat-card"><div class="stat-top"><span>Выручка Webkassa</span><span class="stat-icon cyan"><ReceiptText :size="19" /></span></div><div class="stat-value">{{ formatMoney(complete ? totals.webkassa : null) }} <span>₸</span></div><div class="stat-foot"><span class="source-dot cyan-dot" />{{ totals.tickets }} чеков за период</div></article><article class="stat-card difference-card"><div class="stat-top"><span>Общее расхождение</span><span class="stat-icon orange"><ArrowLeftRight :size="19" /></span></div><div class="stat-value orange-text">{{ difference(totalRow)! > 0 ? '+' : '' }}{{ formatMoney(difference(totalRow)) }} <span>₸</span></div><div class="stat-foot"><span class="percent-badge">{{ formatPercent(percent(totalRow)) }}</span>от выручки Metrix</div></article><article class="stat-card"><div class="stat-top"><span>Дни без расхождений</span><span class="stat-icon green"><CheckCheck :size="19" /></span></div><div class="stat-value">{{ matched }} <span class="out-of">/ {{ rows.length }} дней</span></div><div class="stat-foot"><div class="progress-track"><span :style="{ width: `${matched / rows.length * 100}%` }" /></div><span>{{ Math.round(matched / rows.length * 100) }}%</span></div></article></div>
    <BaseRevenueChart :rows="rows" @detail="detail = $event" />
    <section class="card report-table"><div class="section-heading"><div class="section-title"><h2>Детализация по дням</h2><span class="count-badge">{{ rows.length }}</span></div><div class="export-actions no-print"><button class="btn small-btn" :disabled="stale || busy || exporting" @click="excel"><FileSpreadsheet :size="16" />{{ exporting ? 'Создаем…' : 'Excel' }}</button><button class="btn small-btn" :disabled="stale || busy" @click="print"><FileText :size="16" />PDF</button></div></div><div class="table-toolbar no-print"><div class="tabs"><button :class="{ selected: tab === 'all' }" @click="tab = 'all'">Все дни <span>{{ rows.length }}</span></button><button :class="{ selected: tab === 'diff' }" @click="tab = 'diff'">Расхождения <span class="orange-text">{{ mismatch }}</span></button><button :class="{ selected: tab === 'matched' }" @click="tab = 'matched'">Совпадения <span>{{ matched }}</span></button><button v-if="!complete" :class="{ selected: tab === 'errors' }" @click="tab = 'errors'">Нет данных</button></div><label class="table-search"><Search :size="16" /><input v-model="search" aria-label="Поиск по дате" placeholder="Поиск по дате" /></label></div><div class="table-scroll"><table><thead><tr><th>Дата <span>↓</span></th><th>Metrix, ₸</th><th>Webkassa, ₸</th><th>Разница, ₸</th><th>Разница, %</th><th>Статус</th><th class="no-print" /></tr></thead><tbody><tr v-for="row in filtered" :key="row.date" :class="{ 'diff-row': difference(row) !== 0 && difference(row) !== null }"><td><b>{{ formatDate(row.date) }}</b><span class="day-name">{{ new Date(row.date).toLocaleDateString('ru-RU', { weekday: 'short', timeZone: 'Asia/Almaty' }) }}</span></td><td>{{ formatMoney(row.metrix) }}</td><td>{{ formatMoney(row.webkassa) }}</td><td :class="{ 'orange-text': difference(row) !== 0 }">{{ difference(row)! > 0 ? '+' : '' }}{{ formatMoney(difference(row)) }}</td><td :class="{ 'orange-text': difference(row) !== 0 }">{{ formatPercent(percent(row)) }}</td><td><span :class="['row-status', row.error || difference(row) === null ? 'unknown' : difference(row) === 0 ? 'matched' : 'different']"><Check v-if="difference(row) === 0 && !row.error" :size="13" /><CircleAlert v-else :size="13" />{{ label(row) }}</span></td><td class="no-print"><button class="icon-btn" :aria-label="`Подробности за ${formatDate(row.date)}`" @click="detail = row"><ChevronRight :size="16" /></button></td></tr><tr v-if="!filtered.length"><td colspan="7" class="empty-table">Нет дней, соответствующих фильтру</td></tr></tbody><tfoot><tr><td>Итого за период</td><td>{{ formatMoney(totalRow.metrix) }}</td><td>{{ formatMoney(totalRow.webkassa) }}</td><td class="orange-text">{{ difference(totalRow)! > 0 ? '+' : '' }}{{ formatMoney(difference(totalRow)) }}</td><td class="orange-text">{{ formatPercent(percent(totalRow)) }}</td><td colspan="2">{{ complete ? `${mismatch} дн. с расхождениями` : 'Данные неполные' }}</td></tr></tfoot></table></div><div class="table-footer"><span><Info :size="14" />Разница = Webkassa − Metrix. Процент рассчитан относительно Metrix.</span><span class="no-print">Показано {{ filtered.length }} из {{ rows.length }} дней</span></div></section>
    <div class="report-context"><span>Кассы: {{ report.cashboxes.join(', ') }} · {{ report.mode === 'net' ? 'Продажи минус возвраты' : 'Только продажи' }} · KZT</span><span>Сформирован: {{ new Date(report.createdAt).toLocaleString('ru-RU', { timeZone: 'Asia/Almaty' }) }}</span></div>
    </template><section v-else class="card empty-state"><div class="empty-icon"><ArrowLeftRight :size="32" /></div><h2>Загрузите данные за выбранный период</h2><p>{{ source === 'both' ? 'Подключите оба сервиса, выберите кассы и период.' : `Подключите ${source === 'metrix' ? 'Metrix' : 'Webkassa'}, укажите кассы и период.` }}<br>Дневные суммы появятся здесь.</p></section>
    <footer class="page-footer no-print"><span>© {{ new Date().getFullYear() }} Metrix. Финансы в деталях.</span><span><ShieldCheck :size="14" />Точность, на которую можно опереться</span></footer>
  </div>
  <div v-if="auth" class="modal-backdrop no-print" @click.self="!connecting && (auth = null)"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="auth-title" @keydown.esc="!connecting && (auth = null)"><button class="modal-close icon-btn" aria-label="Закрыть" :disabled="connecting" @click="auth = null"><X :size="20" /></button><span class="modal-symbol"><Plug :size="25" /></span><h2 id="auth-title">Подключение {{ auth === 'metrix' ? 'Metrix' : 'Webkassa' }}</h2><p>Авторизуйтесь для автоматического получения данных. Пароль не сохраняется.</p><form @submit.prevent="connect"><label class="field"><span>{{ auth === 'metrix' ? 'Номер телефона' : 'Логин' }}</span><input v-model="login" :type="auth === 'metrix' ? 'tel' : 'text'" autocomplete="username" required autofocus :placeholder="auth === 'metrix' ? '+7 …' : 'Ваш логин'" /></label><label class="field"><span>Пароль</span><input v-model="password" type="password" autocomplete="current-password" required placeholder="Введите пароль" /></label><p v-if="authError" class="orange-text" role="alert">{{ authError }}</p><button class="btn primary full-width" :disabled="connecting"><LoaderCircle v-if="connecting" :size="17" class="spin" />{{ connecting ? 'Подключение…' : 'Подключить сервис' }}</button></form><small class="muted">Токены хранятся на сервере. Сессия действует до 8 часов.</small></section></div>
  <div v-if="detail" class="modal-backdrop no-print" @click.self="detail = null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="detail-title" @keydown.esc="detail = null"><button class="modal-close icon-btn" aria-label="Закрыть" @click="detail = null"><X :size="20" /></button><h2 id="detail-title">{{ formatDate(detail.date) }}</h2><p>{{ report?.mall }} · {{ report?.tenant }}</p><dl class="detail-list"><div><dt>Metrix</dt><dd>{{ formatMoney(detail.metrix) }} ₸</dd></div><div><dt>Webkassa</dt><dd>{{ formatMoney(detail.webkassa) }} ₸</dd></div><div><dt>Разница</dt><dd class="orange-text">{{ formatMoney(difference(detail)) }} ₸ ({{ formatPercent(percent(detail)) }})</dd></div><div><dt>Чеков учтено</dt><dd>{{ detail.webkassa === null ? '—' : detail.tickets }}</dd></div></dl><p v-if="detail.error" class="orange-text">{{ detail.error }}</p><p v-else>{{ difference(detail) === 0 ? 'Суммы за день совпадают.' : 'Проверьте возвраты, время регистрации чеков и полноту загрузки в Metrix.' }}</p><button class="btn full-width" @click="detail = null">Закрыть</button></section></div>
</template>

<style scoped>
.source-tabs { display: flex; gap: 4px; width: fit-content; max-width: 100%; padding: 4px; margin: 18px 0; background: #f0f4fc; border-radius: 8px; }
.source-tabs button { display: flex; align-items: center; justify-content: center; gap: 7px; padding: 10px 18px; border-radius: 6px; color: #7b8aa4; font-size: 12px; font-weight: 600; }
